    private val _supportMessages = MutableStateFlow(
        listOf(SupportMessage("msg-1", "Support Bot", "Hi there! Welcome to Smart Motos support. How can we help you today?", false, "09:00 AM"))
    )
    val supportMessages: StateFlow<List<SupportMessage>> = _supportMessages.asStateFlow()

    init {
        auth.addAuthStateListener { firebaseAuth ->
            val uid = firebaseAuth.currentUser?.uid
            _isAuthenticated.value = uid != null
            if (uid != null) {
                attachListeners(uid)
            } else {
                detachListeners()
                _currentUser.value = UserProfile(id = "", name = "", email = "", phone = "", role = UserRole.PASSENGER)
                _tripHistory.value = emptyList()
                _pendingTopups.value = emptyList()
                _pendingDrivers.value = emptyList()
        _allUsers.value = emptyList()
            }
        }
    }

    private fun attachListeners(uid: String) {
    userListener?.remove()
    userListener = db.collection("users").document(uid)
        .addSnapshotListener { snapshot, _ ->
            if (snapshot != null && snapshot.exists()) {
                val data = snapshot.data ?: emptyMap()
                val profile = mapUserProfile(uid, data)
                _currentUser.value = profile
                _currentRole.value = profile.role

                if (profile.role == UserRole.ADMIN) {
                    attachAdminListeners()
                } else {
                    detachAdminListeners()
                }
            }
        }

    tripsListener?.remove()
    tripsListener = db.collection("trips")
        .whereEqualTo("riderId", uid)
        .orderBy("createdAt", Query.Direction.DESCENDING)
        .addSnapshotListener { snapshot, _ ->
            if (snapshot != null) {
                _tripHistory.value = snapshot.documents.mapNotNull { mapRideTrip(it.id, it.data ?: return@mapNotNull null) }
            }
        }

    nearbyDriversListener?.remove()
    nearbyDriversListener = db.collection("users")
        .whereEqualTo("role", "driver")
        .whereEqualTo("isAvailableOnline", true)
        .addSnapshotListener { snapshot, _ ->
            if (snapshot != null) {
                _nearbyDrivers.value = snapshot.documents.mapNotNull { doc ->
                    val lat = (doc.get("latitude") as? Number)?.toDouble() ?: return@mapNotNull null
                    val lon = (doc.get("longitude") as? Number)?.toDouble() ?: return@mapNotNull null
                    DriverInfo(
                        id = doc.id,
                        name = doc.getString("name") ?: "",
                        phone = doc.getString("phone") ?: "",
                        rating = 4.8f,
                        plateNumber = doc.getString("licenseNumber") ?: "",
                        avatarUrl = doc.getString("photoUrl") ?: "",
                        currentLocation = LocationPoint("", lat, lon),
                        vehicleType = doc.getString("vehicleType") ?: "Moto"
                    )
                }
            }
        }

    driverTripsListener?.remove()
    driverTripsListener = db.collection("trips")
        .whereEqualTo("driverId", uid)
        .addSnapshotListener { snapshot, _ ->
            if (snapshot != null) {
                val trips = snapshot.documents.mapNotNull { mapRideTrip(it.id, it.data ?: return@mapNotNull null) }
                _incomingDriverRequest.value = trips.firstOrNull { it.status == RideStatus.REQUESTED }
                _activeRide.value = trips.firstOrNull {
                    it.status == RideStatus.DRIVER_ASSIGNED || it.status == RideStatus.DRIVER_ARRIVED || it.status == RideStatus.IN_PROGRESS
                }
            }
        }
