    // collection-wide queries would be denied by firestore.rules anyway,
    // but gating here avoids the wasted listener + permission-denied churn.
    private fun attachAdminListeners() {
        if (topupsListener != null || pendingDriversListener != null) return

        topupsListener = db.collection("topupRequests")
            .whereEqualTo("status", "pending")
            .addSnapshotListener { snapshot, _ ->
                if (snapshot != null) {
                    _pendingTopups.value = snapshot.documents.mapNotNull { doc ->
                        val d = doc.data ?: return@mapNotNull null
                        TopupRequest(
                            id = doc.id,
                            userId = d["userId"] as? String ?: "",
                            userName = d["userName"] as? String ?: "",
                            amountRwf = (d["amountRwf"] as? Number)?.toInt() ?: 0,
                            momoNumber = d["momoNumber"] as? String ?: "",
                            status = d["status"] as? String ?: "pending",
                            timeAgo = "Recently"
                        )
                    }
                }
            }

        allUsersListener?.remove()
        allUsersListener = db.collection("users")
            .addSnapshotListener { snapshot, _ ->
                if (snapshot != null) {
                    _allUsers.value = snapshot.documents.map { doc ->
                        mapUserProfile(doc.id, doc.data ?: emptyMap())
                    }
                }
            }

        pendingDriversListener = db.collection("users")
            .whereEqualTo("driverApplication.status", "pending")
            .addSnapshotListener { snapshot, _ ->
                if (snapshot != null) {
                    _pendingDrivers.value = snapshot.documents.mapNotNull { doc ->
                        val d = doc.data ?: return@mapNotNull null
                        @Suppress("UNCHECKED_CAST")
                        val app = d["driverApplication"] as? Map<String, Any?> ?: emptyMap()
                        UserProfile(
                            id = doc.id,
                            name = d["name"] as? String ?: "",
                            email = d["email"] as? String ?: "",
                            phone = d["phone"] as? String ?: "",
                            role = UserRole.DRIVER,
                            serviceProvider = app["serviceProvider"] as? String ?: "MTN",
                            vehicleType = app["vehicleType"] as? String ?: "Bike",
                            licenseNumber = app["licenseNumber"] as? String ?: "",
                            inspectionCode = app["inspectionCode"] as? String ?: "",
                            verificationStatus = "pending_verification"
                        )
                    }
                }
            }
    }

    private fun detachAdminListeners() {
        topupsListener?.remove(); topupsListener = null
        pendingDriversListener?.remove(); pendingDriversListener = null
        allUsersListener?.remove(); allUsersListener = null
        _pendingTopups.value = emptyList()
        _pendingDrivers.value = emptyList()
    }

    private fun detachListeners() {
        userListener?.remove(); userListener = null
        tripsListener?.remove(); tripsListener = null
        nearbyDriversListener?.remove(); nearbyDriversListener = null
        driverTripsListener?.remove(); driverTripsListener = null
        detachAdminListeners()
    }

    private fun roleFromString(role: String?): UserRole = when (role) {
        "driver" -> UserRole.DRIVER
        "admin" -> UserRole.ADMIN
        else -> UserRole.PASSENGER
    }

    private fun mapUserProfile(id: String, data: Map<String, Any?>): UserProfile {
        @Suppress("UNCHECKED_CAST")
        val driverApp = data["driverApplication"] as? Map<String, Any?>
        return UserProfile(
            id = id,
            name = data["name"] as? String ?: "",
            email = data["email"] as? String ?: "",
            phone = data["phone"] as? String ?: "",
            role = roleFromString(data["role"] as? String),
            photoUrl = data["photoUrl"] as? String,
            walletBalanceRwf = (data["walletBalanceRwf"] as? Number)?.toInt() ?: 0,
            serviceProvider = data["serviceProvider"] as? String ?: "MTN",
            vehicleType = data["vehicleType"] as? String ?: "Bike",
            licenseNumber = data["licenseNumber"] as? String ?: "",
            inspectionCode = driverApp?.get("inspectionCode") as? String ?: "",
            verificationStatus = data["verificationStatus"] as? String ?: "verified",
            isAvailableOnline = data["isAvailableOnline"] as? Boolean ?: true,
            driverApplicationStatus = driverApp?.get("status") as? String,
            latitude = (data["latitude"] as? Number)?.toDouble(),
            longitude = (data["longitude"] as? Number)?.toDouble()
        )
    }

    private fun mapRideTrip(id: String, d: Map<String, Any?>): RideTrip? {
        @Suppress("UNCHECKED_CAST")
        val pickupMap = d["pickup"] as? Map<String, Any?> ?: return null
        @Suppress("UNCHECKED_CAST")
        val dropoffMap = d["dropoff"] as? Map<String, Any?> ?: return null
        return RideTrip(
            id = id,
            riderId = d["riderId"] as? String ?: "",
            orderType = d["orderType"] as? String ?: "Passenger",
            recipientName = d["recipientName"] as? String,
            recipientPhone = d["recipientPhone"] as? String,
            cargoDescription = d["cargoDescription"] as? String,
            riderName = d["riderName"] as? String ?: "",
            driverId = d["driverId"] as? String,
            driverName = d["driverName"] as? String,
            driverAvatar = d["driverAvatar"] as? String,
            driverRating = (d["driverRating"] as? Number)?.toFloat() ?: 4.8f,
            vehiclePlate = d["vehiclePlate"] as? String ?: "",
            pickup = LocationPoint(
                pickupMap["address"] as? String ?: "",
                (pickupMap["latitude"] as? Number)?.toDouble() ?: 0.0,
                (pickupMap["longitude"] as? Number)?.toDouble() ?: 0.0
            ),
            dropoff = LocationPoint(
                dropoffMap["address"] as? String ?: "",
                (dropoffMap["latitude"] as? Number)?.toDouble() ?: 0.0,
                (dropoffMap["longitude"] as? Number)?.toDouble() ?: 0.0
            ),
            status = try { RideStatus.valueOf(d["status"] as? String ?: "REQUESTED") } catch (e: Exception) { RideStatus.REQUESTED },
            fareRwf = (d["fareRwf"] as? Number)?.toInt() ?: 0,
            baseFareRwf = (d["baseFareRwf"] as? Number)?.toInt() ?: 0,
            distanceKm = (d["distanceKm"] as? Number)?.toDouble() ?: 0.0,
            durationMins = (d["durationMins"] as? Number)?.toInt() ?: 0,
            paymentMethod = d["paymentMethod"] as? String ?: "",
            bargainAmountRwf = (d["bargainAmountRwf"] as? Number)?.toInt(),
            ratingGiven = (d["ratingGiven"] as? Number)?.toInt() ?: 0,
            ratingFeedback = d["ratingFeedback"] as? String,
            timestamp = d["timestampLabel"] as? String ?: ""
        )
    }

    // Auth (coroutine-based, matching Elmaz's reliable pattern:
    // single suspend function, timeout-guarded, with rollback on partial failure)

    private const val AUTH_TIMEOUT_MS = 15_000L
    private val timeoutMessage = "Connection timed out. Please check your internet and try again."

    suspend fun signInWithEmail(email: String, password: String): Result<Unit> {
        return try {
            withTimeout(AUTH_TIMEOUT_MS) {
                auth.signInWithEmailAndPassword(email.trim(), password).await()
            }
            registerFcmTokenForCurrentUser()
            Result.success(Unit)
        } catch (e: TimeoutCancellationException) {
            Result.failure(Exception(timeoutMessage))
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun signUpPassenger(email: String, password: String, name: String, phone: String): Result<Unit> {
        return try {
            val authResult = withTimeout(AUTH_TIMEOUT_MS) {
                auth.createUserWithEmailAndPassword(email.trim(), password).await()
            }
            val uid = authResult.user?.uid ?: return Result.failure(Exception("Sign-up failed: no user returned"))
            try {
                withTimeout(AUTH_TIMEOUT_MS) {
                    db.collection("users").document(uid).set(
                        mapOf(
                            "role" to "passenger",
                            "name" to name,
                            "email" to email.trim(),
                            "phone" to phone.trim(),
                            "createdAt" to FieldValue.serverTimestamp()
                        )
                    ).await()
                }
                registerFcmTokenForCurrentUser()
                setRole(UserRole.PASSENGER)
                Result.success(Unit)
            } catch (e: Exception) {
                // Roll back the orphaned Auth account so we never leave a
                // half-registered user with no Firestore profile.
                runCatching { auth.currentUser?.delete()?.await() }
                throw e
            }
        } catch (e: TimeoutCancellationException) {
            Result.failure(Exception(timeoutMessage))
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun signUpDriver(
        email: String,
        password: String,
        name: String,
        phone: String,
        serviceProvider: String,
        vehicleType: String,
        licenseNumber: String,
        inspectionCode: String,
        licensePhotoUri: Uri
    ): Result<Unit> {
        return try {
            val authResult = withTimeout(AUTH_TIMEOUT_MS) {
                auth.createUserWithEmailAndPassword(email.trim(), password).await()
            }
            val uid = authResult.user?.uid ?: return Result.failure(Exception("Sign-up failed: no user returned"))
            try {
                withTimeout(AUTH_TIMEOUT_MS) {
                    db.collection("users").document(uid).set(
                        mapOf(
                            "role" to "passenger",
                            "name" to name,
                            "email" to email.trim(),
                            "phone" to phone.trim(),
                            "driverApplication" to mapOf(
                                "status" to "pending_upload",
                                "serviceProvider" to serviceProvider,
                                "vehicleType" to vehicleType,
                                "licenseNumber" to licenseNumber,
                                "inspectionCode" to inspectionCode
                            ),
                            "createdAt" to FieldValue.serverTimestamp()
                        )
                    ).await()
                }
                registerFcmTokenForCurrentUser()
                setRole(UserRole.PASSENGER)

                // License photo upload happens after the account is safely created;
                // a slow/failed upload should not roll back the whole signup.
                try {
                    val storageRef = FirebaseStorage.getInstance().reference.child("driver_licenses/$uid.jpg")
                    withTimeout(30_000L) { storageRef.putFile(licensePhotoUri).await() }
                    val downloadUrl = storageRef.downloadUrl.await()
                    db.collection("users").document(uid).update(
                        mapOf(
                            "driverApplication.status" to "pending",
                            "driverApplication.licensePhotoUrl" to downloadUrl.toString()
                        )
                    ).await()
                } catch (e: Exception) {
                    android.util.Log.e("Signup", "License photo upload failed", e)
                }
                Result.success(Unit)
            } catch (e: Exception) {
                runCatching { auth.currentUser?.delete()?.await() }
                throw e
            }
        } catch (e: TimeoutCancellationException) {
            Result.failure(Exception(timeoutMessage))
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun signInWithGoogle(idToken: String, defaultRole: UserRole): Result<Unit> {
        return try {
            val credential = GoogleAuthProvider.getCredential(idToken, null)
            val authResult = withTimeout(AUTH_TIMEOUT_MS) {
                auth.signInWithCredential(credential).await()
            }
            val uid = authResult.user?.uid ?: return Result.failure(Exception("No user returned after sign-in"))
            val docRef = db.collection("users").document(uid)
            val doc = withTimeout(AUTH_TIMEOUT_MS) { docRef.get().await() }
            if (!doc.exists()) {
                val roleStr = when (defaultRole) {
                    UserRole.DRIVER -> "driver"
                    UserRole.ADMIN -> "admin"
                    else -> "passenger"
                }
                withTimeout(AUTH_TIMEOUT_MS) {
                    docRef.set(mapOf("role" to roleStr, "email" to (authResult.user?.email ?: ""))).await()
                }
            }
            registerFcmTokenForCurrentUser()
            Result.success(Unit)
        } catch (e: TimeoutCancellationException) {
            Result.failure(Exception(timeoutMessage))
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    // Actions

    fun setRole(role: UserRole) {
        // Local role hint for instant UI feedback; the Firestore listener
        // (attached on auth state change) will overwrite this with the
        // authoritative role + full profile a moment later. No more
        // hardcoded name/phone stomping here.
        _currentRole.value = role
    }

    fun toggleDriverOnline(online: Boolean) {
        _isDriverOnline.value = online
        val uid = auth.currentUser?.uid ?: return
        db.collection("users").document(uid).update("isAvailableOnline", online)
    }
    fun updateDriverLocation(latitude: Double, longitude: Double) {
        val uid = auth.currentUser?.uid ?: return
        db.collection("users").document(uid).update(
            mapOf("latitude" to latitude, "longitude" to longitude)
        )
    }

    fun updateUserProfile(name: String, email: String, phone: String) {
        val uid = auth.currentUser?.uid ?: return
        db.collection("users").document(uid).update(
            mapOf("name" to name, "email" to email, "phone" to phone)
        )
        // Optimistic local update; snapshot listener will confirm shortly.
        _currentUser.value = _currentUser.value.copy(name = name, email = email, phone = phone)
    }

    fun requestWalletTopup(amount: Int) {
        val user = _currentUser.value
        if (user.id.isEmpty()) return
        val newReq = hashMapOf(
            "userId" to user.id,
            "userName" to user.name,
            "amountRwf" to amount,
            "momoNumber" to "0790246983",
            "status" to "pending",
            "createdAt" to FieldValue.serverTimestamp()
        )
        db.collection("topupRequests").add(newReq)
    }

    fun approveTopup(id: String) {
        db.collection("topupRequests").document(id).get().addOnSuccessListener { doc ->
            val userId = doc.getString("userId") ?: return@addOnSuccessListener
            val amount = (doc.getLong("amountRwf") ?: 0L).toInt()
            db.collection("topupRequests").document(id).update("status", "approved")
            db.collection("users").document(userId).update(
                "walletBalanceRwf", FieldValue.increment(amount.toLong())
            )
