    }

    /**
     * Fully deletes a user via Cloud Function: removes both the
     * Firestore profile AND the Firebase Auth login (client SDK
     * alone can only delete the Firestore doc, not another user's
     * Auth account).
     */
    fun deleteUser(userId: String, onResult: ((Boolean, String?) -> Unit)? = null) {
        val data = hashMapOf("userId" to userId)
        functions.getHttpsCallable("adminDeleteUser").call(data)
            .addOnSuccessListener { onResult?.invoke(true, null) }
            .addOnFailureListener { e -> onResult?.invoke(false, e.message) }
    }

    /**
     * Creates a real Firebase Auth account + Firestore profile via
     * Cloud Function. Returns a temp password / reset link the admin
     * can hand to the new user, since this account has no password
     * the user has chosen yet.
     */
    fun addManualUser(
        name: String,
        email: String,
        phone: String,
        role: UserRole,
        onResult: ((Boolean, String?, String?) -> Unit)? = null
    ) {
        val roleStr = when (role) {
            UserRole.DRIVER -> "driver"
            UserRole.ADMIN -> "admin"
            else -> "passenger"
        }
        val data = hashMapOf(
            "name" to name,
            "email" to email.trim(),
            "phone" to phone.trim(),
            "role" to roleStr
        )
        functions.getHttpsCallable("adminCreateUser").call(data)
            .addOnSuccessListener { result ->
                @Suppress("UNCHECKED_CAST")
                val resultData = result.data as? Map<String, Any?>
                val resetLink = resultData?.get("resetLink") as? String
                onResult?.invoke(true, resetLink, null)
            }
            .addOnFailureListener { e -> onResult?.invoke(false, null, e.message) }
    }

    private fun haversineKm(lat1: Double, lon1: Double, lat2: Double, lon2: Double): Double {
        val r = 6371.0
        val dLat = Math.toRadians(lat2 - lat1)
        val dLon = Math.toRadians(lon2 - lon1)
        val a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(Math.toRadians(lat1)) * Math.cos(Math.toRadians(lat2)) *
            Math.sin(dLon / 2) * Math.sin(dLon / 2)
        val c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
        return r * c
    }
    fun createRideRequest(
        pickup: LocationPoint,
        dropoff: LocationPoint,
        paymentMethod: String,
        bargainAmount: Int?,
        orderType: String = "Passenger",
        recipientName: String? = null,
        recipientPhone: String? = null,
        cargoDescription: String? = null
    ) {
        val user = _currentUser.value
        val baseFare = 500

        db.collection("users")
            .whereEqualTo("role", "driver")
            .whereEqualTo("isAvailableOnline", true)
            .get()
            .addOnSuccessListener { snapshot ->
                var nearestId: String? = null
                var nearestName = "Kamana Emmanuel"
                var nearestAvatar = "https://images.pexels.com/photos/1681010/pexels-photo-1681010.jpeg?auto=compress&cs=tinysrgb&w=300"
                var nearestRating = 4.9
                var nearestPlate = "JDM PL8S"
                var nearestDist = Double.MAX_VALUE
                for (doc in snapshot.documents) {
                    val lat = (doc.get("latitude") as? Number)?.toDouble() ?: continue
                    val lon = (doc.get("longitude") as? Number)?.toDouble() ?: continue
                    val d = haversineKm(pickup.latitude, pickup.longitude, lat, lon)
                    if (d < nearestDist) {
                        nearestDist = d
                        nearestId = doc.id
                        nearestName = doc.getString("name") ?: nearestName
                        nearestAvatar = doc.getString("photoUrl") ?: nearestAvatar
                        nearestRating = 4.9
                        nearestPlate = doc.getString("licenseNumber") ?: nearestPlate
                    }
                }
                val dist = if (nearestId != null) nearestDist else 6.4
                val calculatedFare = (baseFare + (dist * 200)).toInt()
                val finalFare = bargainAmount ?: calculatedFare
                val tripData = hashMapOf(
                    "riderId" to user.id,
                    "riderName" to user.name,
                    "driverId" to (nearestId ?: "drv-201"),
                    "driverName" to nearestName,
                    "driverAvatar" to nearestAvatar,
                    "driverRating" to nearestRating,
                    "vehiclePlate" to nearestPlate,
                    "pickup" to mapOf("address" to pickup.address, "latitude" to pickup.latitude, "longitude" to pickup.longitude),
                    "dropoff" to mapOf("address" to dropoff.address, "latitude" to dropoff.latitude, "longitude" to dropoff.longitude),
                    "status" to (if (nearestId != null) "OFFERED" else "NO_DRIVER_FOUND"),
                    "offerStatus" to (if (nearestId != null) "offered" else "none"),
                    "offerExpiresAtMs" to (System.currentTimeMillis() + 20_000L),
                    "fareRwf" to finalFare,
                    "baseFareRwf" to baseFare,
                    "distanceKm" to dist,
                    "durationMins" to 16,
                    "paymentMethod" to paymentMethod,
                    "bargainAmountRwf" to bargainAmount,
                    "orderType" to orderType,
                    "recipientName" to recipientName,
                    "recipientPhone" to recipientPhone,
                    "cargoDescription" to cargoDescription,
                    "createdAt" to FieldValue.serverTimestamp()
                )
                val docRef = db.collection("trips").document()
                docRef.set(tripData)
                val trip = RideTrip(
                    id = docRef.id,
                    riderId = user.id,
                    riderName = user.name,
                    driverId = nearestId ?: "drv-201",
                    driverName = nearestName,
                    driverAvatar = nearestAvatar,
                    driverRating = nearestRating.toFloat(),
                    vehiclePlate = nearestPlate,
                    pickup = pickup,
                    dropoff = dropoff,
                    status = RideStatus.REQUESTED,
                    fareRwf = finalFare,
                    baseFareRwf = baseFare,
                    distanceKm = dist,
                    durationMins = 16,
                    paymentMethod = paymentMethod,
                    bargainAmountRwf = bargainAmount,
                    orderType = orderType,
                    recipientName = recipientName,
                    recipientPhone = recipientPhone,
                    cargoDescription = cargoDescription
                )
                _activeRide.value = trip
                _incomingDriverRequest.value = trip
            }
    }

    fun updateActiveRideStatus(newStatus: RideStatus) {
        val trip = _activeRide.value ?: return
        _activeRide.value = trip.copy(status = newStatus)
        _incomingDriverRequest.value = _incomingDriverRequest.value?.copy(status = newStatus)
        db.collection("trips").document(trip.id).update("status", newStatus.name)

        if (newStatus == RideStatus.COMPLETED) {
            if (trip.paymentMethod.contains("Wallet") || trip.paymentMethod.contains("Mobile")) {
                val currentBal = _currentUser.value.walletBalanceRwf
                if (currentBal >= trip.fareRwf) {
                    db.collection("users").document(trip.riderId).update(
                        "walletBalanceRwf", FieldValue.increment(-trip.fareRwf.toLong())
                    )
                }
            }
        }
    }

    fun submitRating(stars: Int, feedback: String) {
        val trip = _activeRide.value
        if (trip != null) {
            db.collection("trips").document(trip.id).update(
                mapOf("ratingGiven" to stars, "ratingFeedback" to feedback)
            )
        }
        _activeRide.value = null
        _incomingDriverRequest.value = null
    }

    fun listenToTripChat(tripId: String) {
        tripChatListener?.remove()
        _tripChatMessages.value = emptyList()
        tripChatListener = db.collection("trips").document(tripId).collection("messages")
            .orderBy("timestamp")
            .addSnapshotListener { snapshot, _ ->
                if (snapshot != null) {
                    _tripChatMessages.value = snapshot.documents.mapNotNull { doc ->
                        val d = doc.data ?: return@mapNotNull null
                        TripChatMessage(
                            id = doc.id,
                            senderId = d["senderId"] as? String ?: "",
                            senderName = d["senderName"] as? String ?: "",
                            text = d["text"] as? String ?: "",
                            time = ""
                        )
                    }
                }
            }
    }

    fun sendTripChatMessage(tripId: String, text: String) {
        val uid = auth.currentUser?.uid ?: return
        if (text.isBlank()) return
        db.collection("trips").document(tripId).collection("messages").add(
            mapOf(
                "senderId" to uid,
                "senderName" to _currentUser.value.name,
                "text" to text.trim(),
                "timestamp" to FieldValue.serverTimestamp()
            )
        )
    }

    fun detachTripChat() {
        tripChatListener?.remove()
        tripChatListener = null
        _tripChatMessages.value = emptyList()
    }

    fun addSupportMessage(text: String) {
        val userMsg = SupportMessage(
            id = "msg-${System.currentTimeMillis()}",
            senderName = _currentUser.value.name,
            text = text,
            isFromUser = true,
            time = "Just now"
        )
        _supportMessages.value = _supportMessages.value + userMsg

        val botReply = SupportMessage(
            id = "bot-${System.currentTimeMillis()}",
            senderName = "Support Bot",
            text = "Thanks for reaching out! Our team has received your query regarding: \"$text\". An agent will assist you shortly.",
            isFromUser = false,
            time = "Just now"
        )
        _supportMessages.value = _supportMessages.value + botReply
    }
