    // ---------------------------------------------------------
    // Driver offer/accept loop (fixes silent auto-assignment)
    // ---------------------------------------------------------
    fun acceptRideOffer(tripId: String) {
        val uid = auth.currentUser?.uid ?: return
        db.collection("trips").document(tripId).update(
            mapOf(
                "offerStatus" to "accepted",
                "driverId" to uid,
                "status" to "DRIVER_ASSIGNED"
            )
        )
    }

    fun declineRideOffer(tripId: String) {
        db.collection("trips").document(tripId).update(
            mapOf(
                "offerStatus" to "declined",
                "status" to "SEARCHING",
                "driverId" to null
            )
        )
        redispatchTrip(tripId)
    }

    fun expireRideOfferIfTimedOut(tripId: String, offerExpiresAtMs: Long) {
        if (System.currentTimeMillis() < offerExpiresAtMs) return
        db.collection("trips").document(tripId).get().addOnSuccessListener { doc ->
            if (doc.getString("offerStatus") == "offered") {
                db.collection("trips").document(tripId).update(
                    mapOf("offerStatus" to "expired", "status" to "SEARCHING", "driverId" to null)
                )
                redispatchTrip(tripId)
            }
        }
    }

    private fun redispatchTrip(tripId: String) {
        db.collection("trips").document(tripId).get().addOnSuccessListener { doc ->
            val pickupMap = doc.get("pickup") as? Map<*, *> ?: return@addOnSuccessListener
            val lat = (pickupMap["latitude"] as? Number)?.toDouble() ?: return@addOnSuccessListener
            val lon = (pickupMap["longitude"] as? Number)?.toDouble() ?: return@addOnSuccessListener
            val excludeDriverId = doc.getString("driverId")

            db.collection("users")
                .whereEqualTo("role", "driver")
                .whereEqualTo("isAvailableOnline", true)
                .get()
                .addOnSuccessListener { snapshot ->
                    var nearestId: String? = null
                    var nearestDist = Double.MAX_VALUE
                    for (d in snapshot.documents) {
                        if (d.id == excludeDriverId) continue
                        val dLat = (d.get("latitude") as? Number)?.toDouble() ?: continue
                        val dLon = (d.get("longitude") as? Number)?.toDouble() ?: continue
                        val dist = haversineKm(lat, lon, dLat, dLon)
                        if (dist < nearestDist) {
                            nearestDist = dist
                            nearestId = d.id
                        }
                    }
                    if (nearestId != null) {
                        db.collection("trips").document(tripId).update(
                            mapOf(
                                "driverId" to nearestId,
                                "offerStatus" to "offered",
                                "offerExpiresAtMs" to (System.currentTimeMillis() + 20_000L),
                                "status" to "OFFERED"
                            )
                        )
                    } else {
                        db.collection("trips").document(tripId).update(
                            mapOf("status" to "NO_DRIVER_FOUND", "offerStatus" to "none")
                        )
                    }
                }
        }
    }

    // ---------------------------------------------------------
    // Server-transaction-style wallet deduction (avoids client-trusted balance math)
    // ---------------------------------------------------------
    fun settleTripPaymentTransactionally(tripId: String, riderId: String, fareRwf: Int, paymentMethod: String) {
        if (!paymentMethod.contains("Wallet") && !paymentMethod.contains("Mobile")) return
        val userRef = db.collection("users").document(riderId)
        db.runTransaction { txn ->
            val snap = txn.get(userRef)
            val bal = (snap.getLong("walletBalanceRwf") ?: 0L)
            if (bal >= fareRwf) {
                txn.update(userRef, "walletBalanceRwf", bal - fareRwf)
                txn.update(db.collection("trips").document(tripId), "paymentSettled", true)
            }
        }
    }
